// ─── File: src/main/java/com/bank/core/Account.java ───
package com.bank.core;

import java.io.Serializable;
import java.math.BigDecimal;

public class Account implements Serializable {
    private static final long serialVersionUID = 1L;

    // STATIC: class-level shared config — NOT serialized.
    static BigDecimal baseRate = new BigDecimal("6.50");

    // INSTANCE: per-object state — serialized and restored.
    private final String accountId;
    private final BigDecimal balance;

    public Account(String accountId, BigDecimal balance) {
        this.accountId = accountId;
        this.balance = balance;
    }
    public String getAccountId() { return accountId; }
    public BigDecimal getBalance() { return balance; }
}
```

```java
// ─── File: src/main/java/com/bank/core/Store.java ───
package com.bank.core;

import java.io.*;

public class Store {
    public byte[] serialize(Account a) throws IOException {
        ByteArrayOutputStream buffer = new ByteArrayOutputStream();
        try (ObjectOutputStream oos = new ObjectOutputStream(buffer)) {
            oos.writeObject(a);
        }
        return buffer.toByteArray();
    }
    public Account deserialize(byte[] bytes) throws IOException, ClassNotFoundException {
        try (ObjectInputStream ois =
                 new ObjectInputStream(new ByteArrayInputStream(bytes))) {
            return (Account) ois.readObject();
        }
    }
}
```

```java
// ─── File: src/main/java/com/bank/core/StaticSerializationDemo.java ───
package com.bank.core;

import java.math.BigDecimal;
import java.util.logging.*;

public class StaticSerializationDemo {
    private static final Logger log = Logger.getLogger("BankLog");
    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) throws Exception {
        Store store = new Store();
        Account rajesh = new Account("SAV2001", new BigDecimal("1000000.00"));

        log.info(() -> "Before serialize: baseRate=" + Account.baseRate
                        + " balance=" + rajesh.getBalance());

        byte[] bytes = store.serialize(rajesh); // static baseRate is NOT in these bytes

        // Change the shared static value AFTER serializing.
        Account.baseRate = new BigDecimal("7.25");
        log.warning(() -> "Changed static baseRate to " + Account.baseRate);

        Account back = store.deserialize(bytes);
        // Instance balance restored exactly; static baseRate reflects CURRENT value.
        log.info(() -> "After deserialize: balance=" + back.getBalance()
                        + " (restored) baseRate=" + Account.baseRate + " (current, not frozen)");
    }
}
```
